static const char KITTY_EMBEDDED_TUNING_TOML[] =
    "# sdl-kitty tuning: this driver's own choices, keyed by the row ids in\n"
    "# terminals.toml (the shared facts, https://github.com/visionik/terminal-facts).\n"
    "#\n"
    "# Facts go in terminals.toml, not here: what a terminal does is recorded once\n"
    "# for every program that reads it. This file holds what sdl-kitty chooses\n"
    "# given those facts: framebuffer caps, coalescing, drain timing, and so on.\n"
    "#\n"
    "# Resolving (docs/terminal-profiles.md):\n"
    "#   seed in C -> [defaults] -> [terminal.<id>] for each terminals.toml row\n"
    "#   applied, in order (Ghostty 1.3.1: ghostty, then ghostty-1.3), or\n"
    "#   [terminal.unknown] when no row matches -> facts that decide a setting\n"
    "#   -> SDL_KITTY_* environment variables.\n"
    "#\n"
    "# Facts that decide a setting, and win over the keys here:\n"
    "#   kitty.frame_edit_reply = false  -> silent_af_ok = true\n"
    "#   window.ioctl_pixels = false     -> ignore_ioctl_pixels = true\n"
    "#   kitty.max_escape_bytes          -> apc_chunk_bytes (minus 256 for the header)\n"
    "#   kitty.shm = false               -> prefer_direct = true\n"
    "#   kitty.frame_edit = false        -> skip the a=f probe; direct_af_when_shm = false\n"
    "#   kitty.frame_edit_zlib           -> af_zlib\n"
    "#\n"
    "# Compiled into the driver by scripts/update_facts.py; files found at run time\n"
    "# (SDL_KITTY_PROFILES, the pref and base paths) overlay it.\n"
    "\n"
    "[defaults]\n"
    "prefer_direct = false\n"
    "default_fb_max = \"1280x720\"\n"
    "# Transport-aware soft-maxes (0 / omit = fall back to default_fb_max).\n"
    "default_fb_max_shm = \"1280x720\"\n"
    "default_fb_max_direct = \"1280x720\"\n"
    "max_direct_bytes = 8294400          # 1920*1080*4\n"
    "af_max_coverage = 0.40\n"
    "af_max_pixels = 163840              # 160*1024\n"
    "# Compress a=f edits (o=z). Used when kitty.frame_edit_zlib is unknown.\n"
    "af_zlib = false\n"
    "keys_on_stdin = true\n"
    "# Used when kitty.frame_edit_reply is unknown: a strict a=f probe needs OK.\n"
    "silent_af_ok = false\n"
    "# Used when window.ioctl_pixels is unknown.\n"
    "ignore_ioctl_pixels = false\n"
    "direct_af_when_shm = false\n"
    "direct_fallback_max_bytes = 262144  # 256*1024\n"
    "# Used when kitty.max_escape_bytes is unknown.\n"
    "apc_chunk_bytes = 2097152           # 2 MiB\n"
    "probe_timeout_ms = 40\n"
    "drain_passes = 8\n"
    "drain_quiet_us = 15000\n"
    "stub_winch_iters = 40\n"
    "stub_winch_delay_ms = 25\n"
    "stub_cols = 80\n"
    "stub_rows = 24\n"
    "key_hold_ms = 80\n"
    "fb_diff = true\n"
    "fb_diff_tile = 32\n"
    "fb_diff_cover = 0.45\n"
    "tty_pending_max = 4096\n"
    "window_fallback = \"640x480\"\n"
    "place_cells = true\n"
    "pingpong = false\n"
    "# Protocol: terminal unlinks after read; the client must not unlink on success.\n"
    "shm_unlink_after_send = false\n"
    "\n"
    "[terminal.rex]\n"
    "# Facts: no t=s (so prefer_direct), silent a=f replies, untrustworthy ioctl pixels.\n"
    "# Exp 2 Rex soak (2026-10-24): o=z full a=T OK (solid/dirty/alpha); big wire win vs raw.\n"
    "# a=f stays t=d either way. Full a=T takes zlib; a=f with o=z: kitty.frame_edit_zlib.\n"
    "prefer_zlib = true\n"
    "# kitty.storage_bytes = 10 MB; 1080p RGBA is ~8.3 MB, so cap at 720p.\n"
    "default_fb_max = \"1280x720\"\n"
    "default_fb_max_direct = \"1280x720\"\n"
    "# Large dirties -> zlib full a=T (was 1.01 = always a=f, ~2.8 MB/frame on MAME soft).\n"
    "# Watch for a=T flash; kill with SDL_KITTY_AF_MAX_COVERAGE=1.01 if needed.\n"
    "af_max_coverage = 0.40\n"
    "af_max_pixels = 2073600             # 1920*1080\n"
    "direct_af_when_shm = true\n"
    "# Exp 5 Rex soak: alpha_blit 6->1/2; lower upload_px than gap=0.\n"
    "coalesce_gap_px = 2\n"
    "# Keep fb_diff on for MAME soft (tile bbox; no longer expands DIFF_FULL to full FB).\n"
    "fb_diff = true\n"
    "notes = \"prefer_direct+zlib; FB<=720p (10 MB storage); t=s unsupported\"\n"
    "\n"
    "[terminal.kitty]\n"
    "default_fb_max = \"1920x1080\"\n"
    "# SHM: path-only APC; storage 320 MiB, so soft 1080p.\n"
    "default_fb_max_shm = \"1920x1080\"\n"
    "# Direct: chunked under kitty.max_escape_bytes (256 KiB), so soft 720p.\n"
    "default_fb_max_direct = \"1280x720\"\n"
    "# graphics.c: a=f edits root (r=1) with t=d and marks dirty. Historical\n"
    "# \"SHM a=f blank\" was likely client unlink-before-open; keep unlink=false.\n"
    "# Allow direct sparse a=f on SHM sessions; af_max_* caps base64.\n"
    "direct_af_when_shm = true\n"
    "af_max_coverage = 0.40\n"
    "af_max_pixels = 163840\n"
    "# Faster quit drain: hot path uses q=2 so few late APC OK replies.\n"
    "drain_passes = 2\n"
    "drain_quiet_us = 5000\n"
    "notes = \"Kitty: SHM FB 1080p / direct 720p; APC <=256KiB; af_max_* on multi-rect totals\"\n"
    "\n"
    "[terminal.ghostty]\n"
    "# Ghostty >= 1.4 / tip, and the base for ghostty-1.3 (which only changes facts:\n"
    "# no a=f, so no a=f probe and no direct a=f on SHM).\n"
    "default_fb_max = \"1920x1080\"\n"
    "# SHM on; image-storage-limit 320 MB, so soft 1080p.\n"
    "default_fb_max_shm = \"1920x1080\"\n"
    "default_fb_max_direct = \"1280x720\"\n"
    "prefer_zlib = false\n"
    "# Real a=f: allow direct sparse edits while full frames stay SHM.\n"
    "direct_af_when_shm = true\n"
    "# Exp 5 soak: merge near dirty rects before multi a=f.\n"
    "coalesce_gap_px = 2\n"
    "notes = \"Ghostty: SHM 1080p / direct 720p; a=f from 1.4; coalesce=2; APC <=65MiB\"\n"
    "\n"
    "[terminal.wezterm]\n"
    "# Facts: no working a=f (#8281), so full a=T; no t=s on macOS (#8063).\n"
    "# Direct everywhere: t=s on Linux hasn't been soaked yet.\n"
    "prefer_direct = true\n"
    "# Exp 2 soak: zlib o=z instead of raw base64.\n"
    "prefer_zlib = true\n"
    "default_fb_max = \"1280x720\"\n"
    "default_fb_max_direct = \"1280x720\"\n"
    "drain_passes = 2\n"
    "drain_quiet_us = 5000\n"
    "# dirty_at overlays crash WezTerm 20240203; keep multi off.\n"
    "dirty_at_overlays = false\n"
    "# Exp 3 killed: overlays cannot erase stale base without a=f (see optimizations.md).\n"
    "dirty_union_at = false\n"
    "# Exp 6: skip identical full-scratch uploads (FNV).\n"
    "upload_skip = true\n"
    "coalesce_gap_px = 2\n"
    "af_max_coverage = 0.40\n"
    "af_max_pixels = 163840\n"
    "notes = \"WezTerm: prefer_zlib; upload_skip; coalesce=2; no SHM; a=f off; dirty_union off\"\n"
    "\n"
    "[terminal.unknown]\n"
    "# No terminals.toml row matched: a silent a=f probe often means support.\n"
    "silent_af_ok = true\n"
    "notes = \"Fallback when no terminals.toml row matches\"\n";

#endif /* SDL_kittyprofile_data_h_ */
